package staticpod

import (
	"bytes"
	"fmt"
	"strconv"
	"strings"
	"text/template"
)

// ManifestFileName is the name a VM's rendered manifest is written under,
// within its StaticPodPath.
func ManifestFileName(name string) string {
	return "kontur-vm-" + name + ".yaml"
}

// PodName is the Kubernetes pod name a VM's manifest declares.
func PodName(name string) string {
	return "kontur-vm-" + name
}

// Render produces the static pod manifest YAML for spec: one pod with a
// netshim init container (wiring up this VM's tap device, bridge and NAT
// rule) and a single VM container, both running the same kontur image in
// its two modes ("netshim" and "run"). It follows the same shape as
// deploy/static-kubelet/manifests/kontur-static-pod.yaml, generated instead
// of hand-written so it can be regenerated on every "konturctl vm update".
func Render(s VMSpec) (string, error) {
	var buf bytes.Buffer
	if err := manifestTemplate.Execute(&buf, s); err != nil {
		return "", fmt.Errorf("rendering manifest for %q: %w", s.Name, err)
	}
	return buf.String(), nil
}

var manifestTemplate = template.Must(template.New("manifest").Funcs(template.FuncMap{
	"yq":      yamlQuote,
	"itoa":    strconv.Itoa,
	"PodName": PodName,
	"fmtBool": strconv.FormatBool,
}).Parse(netshimEnvTemplateSrc + manifestTemplateSrc))

// yamlQuote renders s as a double-quoted YAML scalar, escaping backslashes
// and double quotes so arbitrary values (paths, cmdlines, image refs) are
// always safe to interpolate regardless of what characters they contain.
func yamlQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '\\', '"':
			b.WriteByte('\\')
			b.WriteRune(r)
		case '\n':
			b.WriteString(`\n`)
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// netshimEnvTemplateSrc is the block of networking settings netshim
// reads, shared by the init container and -- in flat mode, where the VM
// container derives its own --net from the same values -- the VM
// container too, so the two can never disagree.
const netshimEnvTemplateSrc = `{{define "netshimEnv"}}
{{- if .IsFlat}}
        - name: NETSHIM_MODE
          value: {{yq .NetModeOrDefault}}
        - name: NETSHIM_VM
          value: {{yq .Name}}
        - name: NETSHIM_BRIDGE
          value: {{yq .Bridge}}
        - name: NETSHIM_CONTROL_CIDR
          value: {{yq .ControlCIDR}}
        - name: NETSHIM_EXTERNAL_IFACE
          value: {{yq .ExternalIface}}
{{- else}}
        - name: NETSHIM_VMS
          value: {{yq (printf "%s:%s:%d" .Name .IP .Port)}}
        - name: NETSHIM_BRIDGE
          value: {{yq .Bridge}}
        - name: NETSHIM_BRIDGE_CIDR
          value: {{yq .BridgeCIDR}}
        - name: NETSHIM_EXTERNAL_IFACE
          value: {{yq .ExternalIface}}
        - name: NETSHIM_GUEST_PORT
          value: {{yq (itoa .GuestPort)}}
{{- end}}
{{- end}}`

const manifestTemplateSrc = `# Generated by "konturctl vm" -- do not edit by hand, "konturctl vm update"
# will overwrite this file and "konturctl vm delete" removes it. Managed VM: {{.Name}}
apiVersion: v1
kind: Pod
metadata:
  name: {{yq (PodName .Name)}}
  labels:
    app: kontur-vm
    kontur.dev/vm: {{yq .Name}}
spec:
  restartPolicy: Always
  terminationGracePeriodSeconds: {{itoa .TerminationGracePeriodSeconds}}
  initContainers:
    - name: netshim
      image: {{yq .KonturImage}}
      args: ["netshim"]
      env:
{{- template "netshimEnv" .}}
      securityContext:
        # Flat mode never writes net.ipv4.ip_forward and installs no
        # nftables rules, so under docker it runs with CAP_NET_ADMIN and
        # an explicitly granted /dev/net/tun instead (see
        # internal/dockervm). A pod has no per-device grant to give it,
        # and the netlink library creates a tap by opening that device,
        # so here it stays privileged in both modes.
        privileged: true
  containers:
    - name: {{yq .Name}}
      image: {{yq .KonturImage}}
      args: ["run"]
      env:
        - name: CHV_DISK_IMAGE
          value: {{yq .DiskImage}}
        - name: CHV_DISK_MODE
          value: {{yq .DiskModeOrDerived}}
{{- if .Kernel}}
        - name: CHV_KERNEL
          value: {{yq .Kernel}}
{{- end}}
{{- if .Initramfs}}
        - name: CHV_INITRAMFS
          value: {{yq .Initramfs}}
{{- end}}
{{- if .Firmware}}
        - name: CHV_FIRMWARE
          value: {{yq .Firmware}}
{{- end}}
{{- if .Cmdline}}
        - name: CHV_CMDLINE
          value: {{yq .Cmdline}}
{{- end}}
{{- if .IsFlat}}
{{- template "netshimEnv" .}}
{{- else}}
        - name: CHV_NET
          value: {{yq (printf "tap=tap-%s" .Name)}}
{{- end}}
        - name: CHV_CPUS
          value: {{yq (itoa .CPUs)}}
        - name: CHV_MEMORY_MB
          value: {{yq (itoa .MemoryMB)}}
        - name: CHV_SHUTDOWN_TIMEOUT
          value: {{yq .ShutdownTimeout}}
{{- if .ExecAddr}}
        # Lets "kontur exec" (see internal/guestexec) reach this VM's own
        # sshd directly on one of the guest's own NICs, rather than
        # through NETSHIM_GUEST_PORT's external DNAT -- reachable because
        # "kubectl exec"/"docker exec" on this container shares its
        # network namespace with the netshim init container that created
        # that address. In NAT mode that is the guest's address on the
        # private bridge; in flat mode the guest holds the namespace's
        # own address, so it is the control link's instead (and there is
        # no exec path at all without one). Port 22 is fixed: the
        # reference guest image (deploy/guest-image) always runs sshd
        # there.
        - name: KONTUR_EXEC_ADDR
          value: {{yq .ExecAddr}}
{{- end}}
{{- if .GuestUser}}
        # Read twice inside the container, for the two halves of one
        # fact: "kontur run" puts it on the guest's kernel command line so
        # this boot's generated key is authorized for this account, and
        # "kontur exec" logs in as it. See VMSpec.GuestUser.
        - name: KONTUR_EXEC_USER
          value: {{yq .GuestUser}}
{{- end}}
      securityContext:
        privileged: true
      volumeMounts:
        - name: images
          mountPath: /images
          readOnly: true
        - name: kvm
          mountPath: /dev/kvm
  volumes:
    - name: images
      hostPath:
        path: {{yq .ImagesHostPath}}
        type: Directory
    - name: kvm
      hostPath:
        path: /dev/kvm
        type: CharDevice
`
